// Slipper bare gjennom kjente handlinger med strengt validerte verdier. Alt annet blir «avvist».
const b = $json.body || {};
const a = String(b.action || '');
const vm = v => /^\d{3,6}$/.test(String(v));
const list = () => (b.vmids === 'all' || b.vmid === 'all') ? ['all'] : [].concat(b.vmids ?? b.vmid ?? []).map(String);
let command = 'avvist';
if (a === 'audit') command = 'audit';
else if (a === 'verify' && vm(b.vmid)) command = 'verify ' + b.vmid;
else if (a === 'migrate' && vm(b.vmid) && /^pc\d+-ct\d+-[a-z0-9-]{1,40}$/.test(String(b.server_name || ''))) command = `migrate ${b.vmid} ${b.server_name}`;
else if (a === 'map-check') { const l = list(); if (l.length && l.length <= 100 && (l[0] === 'all' ? l.length === 1 : l.every(vm))) command = 'map-check ' + l.join(' '); }
else if (a === 'map-fix') { const l = list(); if (l.length && l.length <= 100 && l.every(vm)) command = 'map-fix ' + l.join(' '); }
else if (a === 'plan-rename' && vm(b.vmid) && /^[a-z0-9][a-z0-9-]{0,39}$/.test(String(b.service || '')))
  command = `plan-rename ${b.vmid} ${b.service}` + (b.start_stop === true ? ' --start-stop' : '') + (b.running_stacks === true ? ' --running-stacks' : '');
else if (a === 'mark' && vm(b.vmid) && /^[a-z0-9-]{2,20}$/.test(String(b.av || '')) && /^[A-Za-z0-9æøåÆØÅ«» .,:\/()→-]{3,140}$/.test(String(b.text || '').trim()))
  command = `mark ${b.vmid} ${b.av} ${String(b.text).trim().replace(/\s+/g, ' ')}`;
else if (a === 'unmark' && vm(b.vmid)) command = 'unmark ' + b.vmid;
else if (a === 'apply' && /^p\d{3,6}-[0-9a-f]{10}$/.test(String(b.plan_id || ''))) command = 'apply ' + b.plan_id;
const error = command === 'avvist'
  ? 'Ugyldig forespørsel. Gyldig: {action:"audit"} | {action:"verify",vmid} | {action:"map-check",vmids:[..]|"all"} | {action:"map-fix",vmids:[..]} | {action:"mark",vmid,av,text} (merk «arbeid pågår» i kartet FØR du begynner) | {action:"unmark",vmid} | {action:"plan-rename",vmid,service[,start_stop,running_stacks]} | {action:"apply",plan_id}'
  : null;
return [{ json: { action: a, command, error, av: String(b.av || 'ukjent').slice(0, 40) } }];

// n8n stoler ikke på ct-ops alene: Proxmox og det publiserte kartet leses på nytt herfra.
const req = $('Valider forespørsel').first().json;
const ssh = $('Kjør ct-ops på pc6').first().json;
let res;
try { res = JSON.parse(ssh.stdout); }
catch (e) { res = { ok: false, status: 'FEILET', error: 'ct-ops svarte ikke med JSON: ' + String(ssh.stderr || ssh.stdout || '').slice(0, 300) }; }
if (req.error) res.error = req.error;
const qc = []; let qcOk = true;
const pass = t => qc.push('✓ ' + t);
const fail = t => { qcOk = false; qc.push('✗ ' + t); };
const guests = ($input.first().json || {}).data || null;
if (['apply', 'verify', 'plan-rename'].includes(req.action) && res.vmid) {
  if (!Array.isArray(guests)) fail('n8n fikk ikke lest Proxmox selv');
  else {
    const me = guests.find(x => x.vmid === res.vmid);
    const claimed = ((req.action === 'apply' ? res.after : (res.inventory || res.before)) || {}).name;
    if (!me) fail(`CT${res.vmid} finnes ikke i Proxmox`);
    else if (claimed && me.name !== claimed) fail(`Proxmox sier «${me.name}», ct-ops sier «${claimed}»`);
    else if (req.action === 'apply' && res.status === 'FERDIG' && me.name !== res.to) fail(`Proxmox sier «${me.name}», men målet var «${res.to}»`);
    else pass(`Proxmox bekrefter CT${res.vmid} = «${me.name}» på ${me.node}`);
  }
}
const HEX = { 'grønn': '#22c55e', 'gul': '#f59e0b', 'rød': '#dc2626' };
const changed = req.action === 'map-fix' ? (res.changed || []) : (req.action === 'apply' ? ((res.map || {}).changed || []) : []);
if (changed.length) {
  let html = '';
  try { html = await this.helpers.httpRequest({ url: 'http://10.0.0.124:3020/', json: false }); } catch (e) { fail('n8n fikk ikke lest det publiserte kartet'); }
  for (const c of (html ? changed : [])) {
    const m = String(html).match(new RegExp('<div class="vm-frame" data-vmid="' + c.vmid + '">[\\s\\S]*?<div class="ct-method" style="[^"]*color:([^;"]+)'));
    const want = HEX[(c.after || {}).color];
    if (m && m[1].trim() === want) pass(`kartet viser CT${c.vmid} som ${c.after.color}`);
    else fail(`kartet viser ikke CT${c.vmid} som ${(c.after || {}).color}`);
  }
}
// «Arbeid pågår»-merket: n8n leser selv at det står (eller er borte) i det publiserte kartet.
const wantMark = (req.action === 'mark' || (req.action === 'plan-rename' && res.plan_id)) ? true : ((req.action === 'unmark' || req.action === 'apply') ? false : null);
if (wantMark !== null && res.vmid) {
  let html = '';
  try { html = await this.helpers.httpRequest({ url: 'http://10.0.0.124:3020/', json: false }); } catch (e) { fail('n8n fikk ikke lest det publiserte kartet'); }
  const m = String(html).match(new RegExp('<div class="vm-frame" data-vmid="' + res.vmid + '">[\\s\\S]*?<div class="ct-method"[^>]*>([\\s\\S]*?)</div>'));
  const has = !!(m && m[1].includes('ARBEID PÅGÅR'));
  if (html && !m) fail(`fant ikke CT${res.vmid} i det publiserte kartet`);
  else if (html && has === wantMark) pass(wantMark ? `kartet viser «arbeid pågår» på CT${res.vmid}` : `kartet har ikke lenger «arbeid pågår» på CT${res.vmid}`);
  else if (html) fail(wantMark ? `kartet viser IKKE «arbeid pågår» på CT${res.vmid}` : `kartet viser fortsatt «arbeid pågår» på CT${res.vmid}`);
}
const ok = !!res.ok && qcOk;
const status = (res.ok && !qcOk) ? 'KVALITETSSJEKK_FEILET' : (res.status || 'FEILET');
let neste = null;
if (req.action === 'plan-rename' && res.plan_id) neste = `Vis stegene til Roger og spør om godkjenning. Etter et tydelig ja: POST {"action":"apply","plan_id":"${res.plan_id}"} innen ${res.valid_minutes} min.`;
else if (req.action === 'plan-rename' && (res.blockers || []).length) neste = 'Planen er blokkert. Gjengi blokkeringene til Roger; ikke prøv en annen vei.';
else if (req.action === 'apply' && !ok) neste = 'IKKE si ferdig. Gjengi status, steg som feilet og gjenstående avvik til Roger.';
let notify = null;
const who = `(bedt om av ${req.av})`;
if (req.action === 'plan-rename' && res.plan_id) notify = { title: `CT-ops: plan venter – CT${res.vmid} → ${res.to}`, text: (res.steps || []).join(' | ').slice(0, 500) + ' ' + who };
else if (req.action === 'apply') notify = { title: `CT-ops ${status}: CT${res.vmid || '?'} → ${res.to || '?'}`, text: ((res.remaining_deviations || []).concat(qc.filter(x => x.startsWith('✗'))).join(' | ') || 'Alt lest tilbake uten avvik.').slice(0, 500) + ' ' + who };
else if (req.action === 'map-fix' && changed.length) notify = { title: `CT-ops ${status}: kart v${res.published_version} – ${changed.length} kort rettet`, text: changed.map(c => `CT${c.vmid} ${(c.before || {}).color || 'mangler'}→${c.after.color}`).join(', ').slice(0, 500) + ' ' + who };
return [{ json: { ok, status, action: req.action, regel: 'Si «ferdig» bare når ok er true. Ellers: gjengi status og avvik ordrett.', kvalitetssjekk: qc, neste, resultat: res, _notify: notify } }];

// Varsler bare når bildet har endret seg siden forrige natt.
let res; try { res = JSON.parse($json.stdout); } catch (e) { res = { status: 'FEILET', error: String($json.stderr || $json.stdout || '').slice(0, 300) }; }
const st = $getWorkflowStaticData('global');
const sig = JSON.stringify([res.status, (res.deviations || []).map(d => [d.vmid, d.n]), (res.map || {}).status, res.map_missing_card, res.error || '']);
const mapChanged = ((res.map || {}).changed || []).length;
if (sig === st.sig && !mapChanged) return [];
const first = st.sig === undefined; st.sig = sig;
if (res.error) return [{ json: { attachments: [{ title: 'CT-ops nattlig revisjon FEILET', text: res.error }], job: 'ct-ops' } }];
const lines = (res.deviations || []).slice(0, 8).map(d => `CT${d.vmid}: ${d.first}`.slice(0, 110));
return [{ json: { attachments: [{ title: `CT-ops: ${res.with_deviations} av ${res.cts} CT-er har avvik${first ? '' : ' (endret siden sist)'}`,
  text: ((mapChanged ? `Kart v${res.map.published_version}: ${mapChanged} statuslinjer oppdatert. ` : '') + ((res.map || {}).status === 'BLOKKERT' ? 'Kart IKKE oppdatert: ' + res.map.error + ' ' : '') + lines.join(' | ')).slice(0, 900) }], job: 'ct-ops' } }];
